Map<String, List<Employee>> deptEmployees = employees.stream()
    .collect(Collectors.groupingBy(Employee::getDepartment));

// WITH mapping: Map<String, List<String>> (names only)
Map<String, List<String>> deptNames = employees.stream()
    .collect(Collectors.groupingBy(Employee::getDepartment,
        Collectors.mapping(Employee::getName, Collectors.toList())));
// {TRADING: ["Rajesh", "Amit", "Neha"], RISK: ["Priya", "Vikram", "Kavita"]}

// mapping + joining: Map<String, String> (CSV of names)
Map<String, String> deptNamesCsv = employees.stream()
    .collect(Collectors.groupingBy(Employee::getDepartment,
        Collectors.mapping(Employee::getName, Collectors.joining(", "))));
// {TRADING: "Rajesh, Amit, Neha", RISK: "Priya, Vikram, Kavita"}

// mapping + toSet: Map<String, Set<String>> (unique cities per department)
Map<String, Set<String>> deptCities = employees.stream()
    .collect(Collectors.groupingBy(Employee::getDepartment,
        Collectors.mapping(Employee::getCity, Collectors.toSet())));
