package com.bank.mapping;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class CollectorsMappingTest {

    record Emp(String name, String dept) {}

    List<Emp> emps = List.of(
        new Emp("Rajesh", "TRADING"), new Emp("Priya", "RISK"),
        new Emp("Amit", "TRADING"), new Emp("Deepa", "RISK"));

    @Test void mappingToNames() {
        Map<String, List<String>> result = emps.stream()
            .collect(Collectors.groupingBy(Emp::dept,
                Collectors.mapping(Emp::name, Collectors.toList())));
        assertThat(result.get("TRADING")).containsExactly("Rajesh", "Amit");
        assertThat(result.get("RISK")).containsExactly("Priya", "Deepa");
    }

    @Test void mappingWithJoining() {
        Map<String, String> result = emps.stream()
            .collect(Collectors.groupingBy(Emp::dept,
                Collectors.mapping(Emp::name, Collectors.joining(", "))));
        assertThat(result.get("TRADING")).isEqualTo("Rajesh, Amit");
    }

    @Test void mappingWithToSet() {
        Map<String, Set<String>> result = emps.stream()
            .collect(Collectors.groupingBy(Emp::dept,
                Collectors.mapping(Emp::name, Collectors.toSet())));
        assertThat(result.get("TRADING")).containsExactlyInAnyOrder("Rajesh", "Amit");
    }
}
