package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.assertThat;

class MappingTest {

    record Account(String id, String branch, String holder) {}

    @Test
    void groupByBranchCollectHolderNames() {
        var accounts = List.of(
            new Account("SAV2001", "MUM", "Rajesh"),
            new Account("CUR3001", "MUM", "Priya"),
            new Account("FD4001",  "DEL", "Amit"));

        Map<String, List<String>> byBranch = accounts.stream()
            .collect(Collectors.groupingBy(Account::branch,
                     Collectors.mapping(Account::holder, Collectors.toList())));

        assertThat(byBranch.get("MUM")).containsExactly("Rajesh", "Priya");
        assertThat(byBranch.get("DEL")).containsExactly("Amit");
    }
}
